<script setup>import {money} from '../services/storage';defineProps({order:Object,advance:Boolean,cancel:Boolean});defineEmits(['advance','cancel'])</script><template><article class="card"><div class="spread"><h2>{{order.queue}}</h2><small>{{order.status}}</small></div><p class="muted">{{order.date}}</p><p v-for="l in order.lines" :key="l.id">{{l.qty}} × {{l.name}} · {{l.variant}}</p><strong>{{money(order.total)}}</strong><div class="actions"><button v-if="advance" @click="$emit('advance',order.id)">Lanjutkan status</button><button class="secondary" v-if="cancel" @click="$emit('cancel',order.id)">Batalkan</button></div></article></template>
